            return memo[n]
        if n == 1:
            return 3
        if n % 2 == 0:
            result = 1 + n / 2
        else:
            result = tribonacci(n - 1, memo) + tribonacci(n - 2, memo) + tribonacci(n + 1, memo)
        memo[n] = result
        return result

